         \fbox{\includegraphics[width=50mm]{figures/no_odd_even/fig7.pdf}}
         \caption{Case 1.1.2 }
         \label{fig:c32}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.4\textwidth}
         \centering
         \fbox{\includegraphics[width=50mm]{figures/no_odd_even/fig8.pdf}}
         \caption{Case 1.2.1 }
         \label{fig:c33}
\end{subfigure}
\hfill
